function makeSubKSumEqual(arr, k) {
  const n = arr.length;
  let step = n;
  let rest = k;
  while (rest !== 0) {
    const remainder = step % rest;
    step = rest;
    rest = remainder;
  }

  let total = 0;
  for (let start = 0; start < step; start++) {
    const group = [];
    for (let i = start; i < n; i += step) {
      group.push(arr[i]);
    }
    group.sort((a, b) => a - b);
    const median = group[group.length >> 1];
    for (const value of group) {
      total += Math.abs(value - median);
    }
  }
  return total;
}

