function makeSubKSumEqual(arr, k) {
  const n = arr.length;
  // Equal window sums force arr[i] === arr[(i + k) % n]; join those indices directly.
  const parent = Array.from({ length: n }, (_, i) => i);
  const find = x => (parent[x] === x ? x : (parent[x] = find(parent[x])));
  for (let i = 0; i < n; i++) parent[find(i)] = find((i + k) % n);
  const groups = new Map();
  for (let i = 0; i < n; i++) {
    const root = find(i);
    if (!groups.has(root)) groups.set(root, []);
    groups.get(root).push(arr[i]);
  }
  let total = 0;
  for (const values of groups.values()) {
    let best = Infinity;
    for (const target of values) {
      let cost = 0;
      for (const v of values) cost += Math.abs(v - target);
      best = Math.min(best, cost);
    }
    total += best;
  }
  return total;
}

