function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(1000, 2000) : int(1, 9);
  const top = rand() < 0.5 ? (size === 'large' ? 1000000000 : 12) : int(1, 1000000000);
  const arr = Array.from({ length: n }, () => int(1, top));
  let k = int(1, n);
  if (rand() < 0.5) {
    // Prefer a k that shares a large factor with n so the groups are many and small.
    const divisors = [];
    for (let d = 1; d <= n; d++) if (n % d === 0) divisors.push(d);
    const d = divisors[Math.floor(rand() * divisors.length)];
    k = d * int(1, Math.floor(n / d));
  }
  return [arr, k];
}
